UPDATE leave_mode
SET budget_amount = #{budgetAmount}
WHERE leave_mode_id = #{leaveModeId}
  AND user_id = #{userId}

UPDATE leave_mode
SET deleted_at = CURRENT_TIMESTAMP,
    is_leave_mode_enabled = FALSE
WHERE leave_mode_id = #{leaveModeId}
  AND user_id = #{userId}
  AND deleted_at IS NULL
